contract InvMutTest {
    C c;
    constructor() payable { c = new C{value: 10 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 salt) public payable {
        uint256 first;
        bool firstOk = true;
        uint256 v1 = c.pastBlockTime(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstOk = false;
        } else {
            first = v1;
        }
        uint256 second;
        bool secondOk = true;
        uint256 v2 = c.pastBlockTime(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondOk = false;
        } else {
            second = v2;
        }
        assert(firstOk && secondOk && first == second);
    }
    receive() external payable {}
}

